window.NPC_CHUNK_275 = [{"name":"Ramona Avandth","cr":4,"xp":1200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":5}],"alignment":"NG","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 armor, +2 Dex","hp":36,"hd":"5d8+10","hd_value":5,"fort":2,"ref":6,"will":4,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","speed":[{"type":"land","speed":30}],"melee":"+1 machete +7 (1d6+1/19-20)","ranged":"mwk shortbow +6 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 14 rounds/day","details":"countersong, distraction, fascinate [DC 14], inspire competence +2, inspire courage +2"}],"spellsknown_caster":"bard","spellsknown_caster_level":5,"spellsknown_concentration":7,"spellsknown":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"animal messenger"},{"spell":"glitterdust"},{"spell":"tongues"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm person"},{"spell":"feather fall"},{"spell":"grease"},{"spell":"vanish"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"know direction"},{"spell":"mage hand"},{"spell":"message"},{"spell":"sift"},{"spell":"unwitting ally"}]}],"strength":10,"dexterity":14,"constitution":12,"intelligence":14,"wisdom":10,"charisma":15,"baseatk":3,"cmb":3,"cmd":15,"feats":[{"feat":"Martial Weapon Proficiency (machete)"},{"feat":"Point-Blank Shot"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (machete)"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Bluff","value":10},{"skill":"Climb","value":4},{"skill":"Intimidate","value":7},{"skill":"Knowledge (geography, local, nature)","value":10},{"skill":"Knowledge (history)","value":12},{"skill":"Perception","value":7},{"skill":"Perform (oratory, sing)","value":10},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":10}],"languages":["Common","Dwarven","Elven"],"sq":["bardic knowledge +2","lore master 1/day","versatile performance (oratory)"],"gear":"mwk studded leather, +1 machete, mwk shortbow with 20 arrows, belt pouch, compass, ink, inkpen, journal, paper (10), scroll case, spell component pouch","source":"AP 121"},{"name":"Colonial Soldier","cr":1,"xp":400,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":2}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+6 armor, +1 Dex","hp":21,"hd":"2d10+6","hd_value":2,"fort":5,"ref":1,"will":1,"save_mods":"Will: +1 vs. fear","speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"longsword +5 (1d8+2/19-20)","ranged":"longbow +3 (1d8/x3)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":12,"constitution":14,"intelligence":8,"wisdom":13,"charisma":10,"baseatk":2,"cmb":4,"cmd":15,"feats":[{"feat":"Dazzling Display"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Acrobatics","value":-3,"special":"-4 when jumping"},{"skill":"Climb","value":2},{"skill":"Intimidate","value":4},{"skill":"Perception","value":2},{"skill":"Survival","value":5}],"languages":["Common"],"gear":"breastplate, longbow with 20 arrows, longsword, canteen, flint and steel, mess kit, torches (2), potion of cure light wounds","source":"AP 121"},{"name":"Efwurwa","cr":9,"xp":6400,"race":"invisible stalker","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":1},{"class":"rogue","level":1}],"alignment":"NE","size":"Medium","type":"outsider","sub_types":["air","elemental","extraplanar"],"init":10,"senses":["darkvision 60 ft."],"ac":23,"ac_touch":16,"ac_flat_footed":17,"ac_mods":"+1 armor, +6 Dex, +6 natural","hp":112,"hd":"1d8+8d10+64","hd_value":9,"fort":14,"ref":15,"will":4,"defensive_abilities":["natural invisibility"],"immunities":["elemental traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"},{"type":"land","speed":30}],"melee":"+1 menacing greatsword +15 (2d6+10/19-20) or 2 slams +10 (2d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":22,"dexterity":23,"constitution":24,"intelligence":16,"wisdom":15,"charisma":9,"baseatk":8,"cmb":14,"cmd":30,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Outflank"},{"feat":"Precise Strike"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Bluff","value":11},{"skill":"Escape Artist","value":16},{"skill":"Fly","value":26},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":18,"special":"+20 while moving or +40 while still vs. foes who can't see invisible"},{"skill":"Survival","value":14}],"languages":["Common","Auran","Gnome"],"sq":["improved tracking","trapfinding +1"],"special_abilities":[{"type":"Natural Invisibility","kind":"Ex","details":"Efwurwa's invisibility extends to her gear."}],"gear":"+1 menacing greatsword, bracers of armor +1","during_combat":"If any PC indicates that he can see invisible creatures, Efwurwa barks an order in Auran for all the Furies to gang up on that one person. Otherwise, she positions herself to flank multiple PCs, if possible, maximizing the benefits of her teamwork feats and menacing sword.","morale":"Efwurwa fights as long as there is an elemental left alive. If all her minions have fallen, she flees. In either case, she plays no further role in the scenario.","source":"PFS 8-24, Pathfinder RPG Bestiary 181"},{"name":"Bozhithar","cr":5,"xp":1600,"race":"hala demon","gender":"Male","age_category":"Adult","alignment":"CE","size":"Medium","type":"outsider","sub_types":["air","chaotic","demon","evil","extraplanar"],"init":4,"senses":["darkvision 60 ft."],"auras":["stormwind aura"],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 Dex, +4 natural","hp":51,"hd":"6d10+18","hd_value":6,"fort":7,"ref":8,"will":3,"defensive_abilities":["vengeful wind"],"dr":"5/cold iron or good","immunities":["electricity","poison"],"resists":["acid 10","cold 10","fire 10"],"sr":16,"weaknesses":["enemy of dragons and eagles"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"},{"type":"land","speed":30}],"melee":"bite +11 (1d6+4), 2 claws +11 (1d4+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hailstorm"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"alter winds"}]},{"frequency":"1/day","spells":[{"spell":"control winds"}]},{"frequency":"3/day","spells":[{"spell":"gust of wind"},{"spell":"river of wind"}]}],"strength":18,"dexterity":19,"constitution":16,"intelligence":16,"wisdom":15,"charisma":17,"baseatk":6,"cmb":10,"cmd":24,"feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Weapon Finesse"},{"feat":"Wingover"}],"skills":[{"skill":"Acrobatics","value":13},{"skill":"Escape Artist","value":13},{"skill":"Fly","value":21},{"skill":"Intimidate","value":13},{"skill":"Knowledge (engineering)","value":9},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":11},{"skill":"Stealth","value":13}],"languages":["Common","Abyssal","Auran","Celestial","Draconic","telepathy 100 ft."],"special_abilities":[{"type":"Enemy of Dragons and Eagles","kind":"Ex","details":"Halas are hated enemies of dragons and eagles. Those creatures gain a +2 bonus on attack and damage rolls against hala demons."},{"type":"Hailstorm","kind":"Su","details":"A hala can call down hailstones from surrounding clouds once every 1d4 rounds as a standard action. These hailstones deal 1d6 points of bludgeoning damage and 1d6 points of cold damage to all creatures within a 20-foot radius that have no overhead cover. A DC 16 Reflex save halves this damage. The save DC is Constitution-based. To use this ability, the hala must be outside and there must be clouds in the sky."},{"type":"Stormwind Aura","kind":"Su","details":"Halas surround themselves with a buffeting shroud of supernatural, windstorm-force winds. These winds shield a hala from any other wind effects and form a shell of breathable air around it, allowing the hala to breathe underwater. Ranged weapons and gases directed toward a hala are affected as per wind wall."},{"type":"Vengeful Wind","kind":"Su","details":"Anytime a hala takes damage from a critical hit, a powerful blast of wind explodes forth in the direction of the attacker. This blast takes the form of a 60-foot-long gale, treated as a gust of wind spell, directed from the hala toward the opponent that scored the critical hit against it (if that creature is more than 60 ft. away, the wind is aimed in its direction but doesn't come close enough to affect it). This wind is also charged with electricity. Any creature in or that enters the area of effect must make a DC 16 Reflex save or take 3d6 points of electricity damage. The save DC is Constitution-based."}],"gear":"golembane scarab, manacles of cooperation","during_combat":"Bozhithar tries to keep enemies at bay by using river of wind or gust of wind and sending hailstorms at them to soften them up. After a few rounds, he closes on the least-armored opponent to finish them in melee.","morale":"Bozhithar is unwilling to face Pazuzu's eventual wrath for failing in his duties. He fights to the death.","source":"PFS 8-24, Pathfinder Adventure Path #49: The Brinewall Legacy 84"},{"name":"Mist Drake","cr":6,"xp":2400,"race":"mist drake","age_category":"Adult","alignment":"NE","size":"Large","type":"dragon","sub_types":["air"],"templates_applied":"advanced","init":4,"senses":["darkvision 60 ft.","fogvision","low-light vision","scent"],"ac":23,"ac_touch":14,"ac_flat_footed":18,"ac_mods":"+4 Dex, +1 dodge, +9 natural, -1 size","hp":69,"hd":"6d12+30","hd_value":6,"fort":10,"ref":9,"will":8,"immunities":["paralysis","sleep"],"speed":[{"type":"fly","speed":80,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"bite +11 (2d6+6), tail slap +6 (1d8+3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"fogburst"}],"strength":23,"dexterity":19,"constitution":20,"intelligence":13,"wisdom":16,"charisma":14,"baseatk":6,"cmb":13,"cmd":28,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Hover"}],"skills":[{"skill":"Fly","value":11},{"skill":"Intimidate","value":11},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":9,"special":"+8 in fog or mist"},{"skill":"Survival","value":12}],"languages":["Auran","Draconic"],"sq":["misty camouflage","speed surge"],"special_abilities":[{"type":"Fogburst","kind":"Su","details":"As a standard action, a mist drake can expel a ball of solid mist that explodes into a cloud of fog upon impact. This attack has a range of 60 ft. and deals 3d6 points of bludgeoning damage to all creatures in a 20-foot radius (Reflex DC 18 half). A flying creatures that fails its Reflex save is pushed 1d4x5 ft. from the center of the fogburst's area of effect (taking 1d6 points of damage per 10 ft. if it strikes a solid object), while creatures on the ground are knocked prone on a failed save. The area of effect of the fogburst is filled with mist (as per obscuring mist) for 1d4 rounds after impact. Once a mist drake has used its fogburst attack, it cannot do so again for 1d6 rounds. The save DC is Constitution-based."},{"type":"Fogvision","kind":"Ex","details":"A mist drake can see normally through any form of natural or magical mist, fog, or precipitation."},{"type":"Misty Camouflage","kind":"Ex","details":"A mist drake can use Stealth to hide whenever it is in or adjacent to an area of mist, even while being observed."},{"type":"Speed Surge","kind":"Ex","details":"Three times per day as a swift action, a mist drake can draw on its draconic heritage for a boost of strength and speed that enables it to take an additional move action in that round."}],"gear":"horn of fog (one drake only), wind fan (one drake only)","during_combat":"The drakes attempt to disorient the PCs with fogbursts and then hide within the created clouds, making hit-and-run attacks from concealment.","morale":"The drakes fear death more than even Bozhithar and Grasping Storm. They flee into the sky if reduced to 15 hit points or fewer.","source":"PFS 8-24, Pathfinder RPG Bestiary 4 288, 79"},{"name":"Bozhithar Subtier 8-9","cr":8,"xp":4800,"race":"hala demon","gender":"Male","age_category":"Adult","alignment":"CE","size":"Medium","type":"outsider","sub_types":["air","chaotic","demon","evil","extraplanar"],"init":6,"senses":["darkvision 60 ft."],"auras":["stormwind aura"],"ac":22,"ac_touch":16,"ac_flat_footed":16,"ac_mods":"+6 Dex, +6 natural","hp":95,"hd":"10d10+40","hd_value":10,"fort":12,"ref":14,"will":6,"defensive_abilities":["vengeful wind"],"dr":"10/good or cold iron","immunities":["electricity","poison"],"resists":["acid 10","cold 10","fire 10"],"sr":19,"weaknesses":["enemy of dragons and eagles"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"},{"type":"land","speed":30}],"melee":"bite +16 (1d6+5), 2 claws +16 (1d4+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hailstorm"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"alter winds"}]},{"frequency":"1/day","spells":[{"spell":"control winds"}]},{"frequency":"3/day","spells":[{"spell":"gust of wind"},{"spell":"river of wind"}]}],"strength":20,"dexterity":23,"constitution":18,"intelligence":16,"wisdom":15,"charisma":19,"baseatk":10,"cmb":16,"cmd":32,"feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claw)"},{"feat":"Wingover"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Escape Artist","value":19},{"skill":"Fly","value":27},{"skill":"Intimidate","value":17},{"skill":"Knowledge (engineering)","value":13},{"skill":"Knowledge (planes)","value":16},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":19}],"languages":["Common","Abyssal","Auran","Celestial","Draconic","telepathy 100 ft."],"special_abilities":[{"type":"Enemy of Dragons and Eagles","kind":"Ex","details":"Halas are hated enemies of dragons and eagles. Those creatures gain a +2 bonus on attack and damage rolls against hala demons."},{"type":"Hailstorm","kind":"Su","details":"A hala can call down hailstones from surrounding clouds once every 1d4 rounds as a standard action. These hailstones deal 1d6 points of bludgeoning damage and 1d6 points of cold damage to all creatures within a 30-foot radius that have no overhead cover. A DC 18 Reflex save halves this damage. The save DC is Constitution-based. To use this ability, the hala must be outside and there must be clouds in the sky."},{"type":"Stormwind Aura","kind":"Su","details":"Halas surround themselves with a buffeting shroud of supernatural, windstorm-force winds. These winds shield a hala from any other wind effects and form a shell of breathable air around it, allowing the hala to breathe underwater. Ranged weapons and gases directed toward a hala are affected as per wind wall."},{"type":"Vengeful Wind","kind":"Su","details":"Anytime a hala takes damage from a critical hit, a powerful blast of wind explodes forth in the direction of the attacker. This blast takes the form of a 60-foot-long gale, treated as a gust of wind spell, directed from the hala toward the opponent that scored the critical hit against it (if that creature is more than 60 ft. away, the wind is aimed in its direction but doesn't come close enough to affect it). This wind is also charged with electricity. Any creature in or that enters the area of effect must make a DC 18 Reflex save or take 4d6 points of electricity damage. The save DC is Constitution-based."}],"gear":"cloak of resistance +1, golembane scarab, manacles of cooperation, potion of cure serious wounds","during_combat":"Bozhithar tries to keep enemies at bay with river of wind or gust of wind and sending hailstorms at them to soften them up. After a few rounds, he closes on the least-armored opponent to finish them in melee.","morale":"Bozhithar is unwilling to face Pazuzu's eventual wrath for failing in his duties. He fights to the death.","source":"PFS 8-24, Pathfinder Adventure Path #49: The Brinewall Legacy 84"},{"name":"Advanced Hungry Fog","cr":7,"xp":3200,"race":"Advanced Hungry Fog","age_category":"Adult","alignment":"N","size":"Huge","type":"ooze","init":-1,"auras":["bewitching brume (10 ft., DC 10)"],"ac":9,"ac_touch":7,"ac_flat_footed":9,"ac_mods":"-1 Dex, +2 natural, -2 size","hp":73,"hd":"7d8+42","hd_value":7,"fort":8,"ref":1,"will":-1,"defensive_abilities":["gaseous","negative energy affinity"],"dr":"10/ magic","immunities":["acid","electricity","ooze traits","sonic"],"resists":["cold 10"],"weaknesses":["vulnerability to wind"],"speed":[{"type":"fly","speed":15,"maneuverability":"perfect"}],"melee":"touch +5 (6d6 negative energy)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"enveloping mists","details":"3d6 negative energy and staggered, DC 21"}],"dexterity":8,"constitution":22,"wisdom":5,"charisma":5,"baseatk":5,"cmb":7,"cmd":16,"cmd_special":"can't be tripped","skills":[{"skill":"Fly","value":3}],"special_abilities":[{"type":"Bewitching Brume","kind":"Su","details":"Any creature within 10 ft. of a hungry fog or currently being affected by its enveloping mists must succeed on a DC 10 Will save at the start of that creature's turn or become shaken for 1 round at the half-glimpsed shapes of phantoms floating within the fog. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Enveloping Mists","kind":"Ex","details":"A hungry fog can engulf foes who fail a Reflex save, as per the engulf universal monster rule. A creature engulfed by a hungry fog doesn't gain the pinned condition and may move normally-such a creature isn't in danger of suffocating, but as long as it begins its turn engulfed, it is staggered in addition to the damage the attack causes. The save DC to avoid the enveloping mists is Constitution-based."},{"type":"Gaseous","kind":"Ex","details":"A hungry fog has a body composed of eerie mist. It can pass through small holes or narrow openings, even mere cracks, but cannot enter water or other liquid. It has no Strength score, and cannot manipulate objects as a result."},{"type":"Vulnerable to Wind","kind":"Ex","details":"A hungry fog is treated as a Tiny creature for the purposes of determining the effects high wind has upon it."}],"during_combat":"The fog floats over and engulfs the PCs. If damaged for more than half its hit points, it flies upwards and attacks using its reach.","morale":"Starving and mindless, the hungry fog fights until killed.","source":"PFS 8-24, Pathfinder RPG Bestiary 3 290, 152"},{"name":"Siveya And Tekaal","cr":4,"xp":1200,"race":"sylph","gender":"Male and Female","age_category":"Adult","classes":[{"class":"druid","level":5,"archetype":"sky druid"}],"alignment":"N","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft."],"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+4 armor, +2 Dex, +1 dodge, +2 natural, +1 shield","hp":41,"hd":"5d8+15","hd_value":5,"fort":5,"ref":3,"will":9,"save_mods":"+4 vs. air or electricity descriptor spells or effects that control or modify the weather","resists":["electricity 5"],"speed":[{"type":"land","speed":30}],"melee":"+1 club +5 (2d6+2)","ranged":"sling +5 (1d4+1)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"feather fall"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":5,"spellsprepared_concentration":10,"spellsprepared":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"call lightning"},{"spell":"gaseous form","type":"domain"},{"spell":"summon nature's ally III"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"barkskin"},{"spell":"chill metal"},{"spell":"owl's wisdom"},{"spell":"wind wall","type":"domain"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"cure light wounds"},{"spell":"faerie fire"},{"spell":"obscuring mist"},{"spell":"shillelagh"},{"spell":"whispering wind","type":"domain"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"flare"},{"spell":"light"},{"spell":"resistance"},{"spell":"stabilize"}]}],"spelldomains":"Air","strength":12,"dexterity":15,"constitution":12,"intelligence":10,"wisdom":20,"charisma":10,"baseatk":3,"cmb":4,"cmb_special":"+10 using wind blast","cmd":17,"feats":[{"feat":"Cloud Gazer"},{"feat":"Dodge"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":9},{"skill":"Knowledge (nature)","value":10},{"skill":"Knowledge (planes)","value":5},{"skill":"Spellcraft","value":8},{"skill":"Survival","value":5}],"languages":["Common","Auran","Druidic"],"sq":["nature bond (Wind domain)","nature sense","resist storm","sky's embrace","skymaster","wild empathy +5","wind blast"],"gear":"+1 darkwood wooden armor, light wooden shield, club, holly and mistletoe, spell component pouch, scroll of cure light wounds","before_combat":"If they are on alert, the two sylphs cast barkskin, call lightning, owl's wisdom, and shillelagh, and they activate their skymaster ability.","during_combat":"The sylphs cast obscuring mist, which their Cloud Gazer feat lets them see through. Each sylph casts summon nature's ally III to summon 1d3 small air elementals to harass the PCs. The sylphs assist from behind cloud cover using call lightning (the bolts deal 3d10 points of damage in this room) or wind blasts to bull rush PCs into the hurricane. If they are out of other options or Grasping Storm commands it, they fly to attack using their clubs.","morale":"The sylphs surrender if Grasping Storm dies, but otherwise fight until incapacitated.","base_statistics":"If the PCs haven't raised an alarm, then the  sylphs haven't cast preparatory spells. Adjust their statistics as follows: AC 18, touch 13, flat-footed 15, Will +7, Melee club +4 (1d6+1); Wis 16. Their spell save DCs, concentration check bonus, and wind blast CMB all decrease by 2.","source":"PFS 8-24, Pathfinder RPG Advanced Race Guide 158, Pathfinder RPG Bestiary 2 258"},{"name":"Grasping Storm","cr":7,"xp":3200,"race":"belker","age_category":"Adult","alignment":"NE","size":"Large","type":"outsider","sub_types":["air","elemental","evil"],"init":5,"senses":["darkvision 60 ft."],"ac":20,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+5 Dex, +6 natural, -1 size","hp":68,"hd":"8d10+24","hd_value":8,"fort":9,"ref":11,"will":2,"dr":"5/-","immunities":["electricity","elemental traits"],"resists":["sonic 5"],"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"},{"type":"land","speed":30}],"melee":"bite +12 (1d6+2), 2 claws +12 (1d6+2), 2 wings +10 (1d6+1)","ranged":"air blast +13 (4d6+7)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"air blast"},{"type":"smoke claws"}],"strength":14,"dexterity":21,"constitution":17,"intelligence":12,"wisdom":11,"charisma":10,"baseatk":8,"cmb":11,"cmb_special":"+13 air blast","cmd":26,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Flyby Attack"},{"feat":"Multiattack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Escape Artist","value":13},{"skill":"Fly","value":22},{"skill":"Intimidate","value":8},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":11},{"skill":"Stealth","value":16}],"languages":["Common","Auran"],"sq":["smoke form","storm's call"],"special_abilities":[{"type":"Smoke Claws","kind":"Ex","details":"A belker using its smoke form ability can enter a target's square as a standard action that doesn't provoke attacks of opportunity. The target must make a DC 17 Fortitude save or inhale part of the creature. Smoke inside the victim solidifies into a claw and attacks the target from within, dealing 3d4 points of damage per round as a swift action. If the target moves, the belker may automatically move with the target (this movement doesn't count toward the belker's movement and doesn't provoke attacks of opportunity against the belker). Each round, the target can attempt another DC 17 Fortitude to cough out the belker's smoke, which ends the smoke claws attack and forces the belker into an adjacent square. Creatures that don't need to breathe are immune to this attack. The save DC is Constitution-based."},{"type":"Smoke Form","kind":"Su","details":"A belker can switch from its normal form to one of pure smoke or back again a swift action. It can spend up to 20 rounds per day in smoke form. In smoke form, the belker acts as if under the effects of a gaseous form spell, except that it retains its natural fly speed of 50 ft. (perfect)."},{"type":"Storm's Call","kind":"Sp","details":"Before Grasping Storm fell out of Hshurha's favor, the elemental lord granted the belker a measure of air blast as a ranged attack with a range of 120 feet. It gains a daily pool of 10 points, which it can spend as a free action for any of the following effects. It must choose how many points it wants to spend before rolling its attack roll. Grasping Storm gains a +2 bonus on combat maneuvers that it makes as a part of using this ability. • Grasping Storm can spend 1 or more points to enhance its air blast with the ability to push its target back. This functions as a bull rush combat maneuver, except that it can push the target back a maximum distance of 5 ft. for every point that the belker spends. • Grasping storm can spend 3 or more points to drag its target closer. If it succeeds at a combat maneuver check against a creature of size Large or smaller, that creature is pulled 15 ft. closer to it, plus an additional 10 ft. for every point that the belker spends."}],"during_combat":"Grasping Storm stays at a distance, using its mobility and air blasts to keep opponents away. It pulls weak-looking foes to itself, then either savages them in melee or uses smoke form and claws to tear them apart from within. It pushes stronger foes into the hurricane, or orders a sylph to physically impede.","morale":"Grasping Storm would rather die than submit to physical beings, and fights to the death.","source":"PFS 8-24, Pathfinder RPG Bestiary 2 45","unique_monster":1},{"name":"Siveya And Tekaal Subtier 8-9","cr":6,"xp":2400,"race":"Sylph","age_category":"Adult","classes":[{"class":"druid","level":7,"archetype":"sky druid"}],"alignment":"N","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft."],"ac":22,"ac_touch":13,"ac_flat_footed":19,"ac_mods":"+4 armor, +2 Dex, +1 dodge, +3 natural, +2 shield","hp":56,"hd":"7d8+21","hd_value":7,"fort":7,"ref":5,"will":11,"save_mods":"+4 vs. air or electricity descriptor spells or effects that control or modify the weather","resists":["electricity 10"],"speed":[{"type":"land","speed":30}],"melee":"+1 club +7 (2d6+2)","ranged":"sling +7 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"wild shape","details":"1/day"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"feather fall"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":7,"spellsprepared_concentration":12,"spellsprepared":[{"spell_level":4,"spell_slots":2,"spells":[{"spell":"air walk","type":"domain"},{"spell":"dispel magic"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"call lightning"},{"spell":"gaseous form","type":"domain"},{"spell":"greater magic fang"},{"spell":"summon nature's ally III"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"barkskin"},{"spell":"chill metal"},{"spell":"owl's wisdom"},{"spell":"summon swarm"},{"spell":"wind wall","type":"domain"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cure light wounds","count":2},{"spell":"faerie fire"},{"spell":"obscuring mist"},{"spell":"shillelagh"},{"spell":"whispering wind","type":"domain"},{"spell":"windy escape"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"flare"},{"spell":"light"},{"spell":"resistance"},{"spell":"stabilize"}]}],"spelldomains":"Air","strength":12,"dexterity":15,"constitution":12,"intelligence":10,"wisdom":20,"charisma":10,"baseatk":5,"cmb":6,"cmb_special":"+12 using wind blast","cmd":19,"feats":[{"feat":"Cloud Gazer"},{"feat":"Dodge"},{"feat":"Natural Spell"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":12},{"skill":"Knowledge (nature)","value":12},{"skill":"Knowledge (planes)","value":7},{"skill":"Spellcraft","value":10},{"skill":"Survival","value":5}],"languages":["Common","Auran","Druidic"],"sq":["nature bond (Wind domain)","nature sense","resist storm","sky's embrace","skymaster","wild empathy +7","wind blast"],"gear":"+1 darkwood wooden armor, +1 darkwood light wooden shield, club, cloak of resistance +1, holly and mistletoe, spell component pouch, scroll of cure moderate wounds (2)","before_combat":"If they are on alert, the two sylphs cast barkskin, call lightning, greater magic fang, owl's wisdom, and shillelagh, and they activate their skymaster ability to fly.","during_combat":"The sylphs cast obscuring mist, which their Cloud Gazer feat lets them see through. Each sylph casts summon nature's ally III to summon 1d3 small air elementals to harass the PCs. The s ylphs assist from behind cloud cover using call lightning (the bolts deal 3d10 points of damage in this room) or wind blasts to bull rush PCs into the hurricane. They use dispel magic to attempt to dispel the PCs' magical methods of flight. If they are out of other options or Grasping Storm commands it, they use wild shape to transform into Medium air elementals and fly in to attack.","morale":"The sylphs surrender if Grasping Storm dies, but otherwise fight until incapacitated.","base_statistics":"If the PCs haven't raised an alarm, then the sylphs haven't cast preparatory spells. Adjust their statistics as follows: AC 19, touch 13, flat-footed 16, Will +9; Melee club +6 (1d6+1); Wis 16. Their spell save DCs, concentration check bonus, and wind blast CMB all decrease by 2.","source":"PFS 8-24, Pathfinder RPG Advanced Race Guide 158, Pathfinder RPG Bestiary 2 258"},{"name":"Avalanche Legion","cr":11,"xp":12800,"race":"Avalanche Legion","age_category":"Adult","alignment":"N","size":"Medium","type":"outsider","sub_types":["earth","elemental","extraplanar"],"init":3,"senses":["darkvision 60 ft.","tremorsense 60 ft."],"auras":["quake aura (5 ft., DC 23)"],"ac":25,"ac_touch":9,"ac_flat_footed":25,"ac_mods":"-1 Dex, +16 natural","hp":168,"hd":"16d10+80","hd_value":16,"fort":17,"ref":4,"will":12,"defensive_abilities":["troop traits"],"dr":"10/-","immunities":["elemental traits"],"speed":[{"type":"burrow","speed":20},{"type":"land","speed":20}],"speed_mod":"earth glide","melee":"troop (4d6+12)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"avalanche","details":"4d6+12; DC 23"},{"type":"volley"}],"strength":34,"dexterity":8,"constitution":21,"intelligence":10,"wisdom":11,"charisma":11,"baseatk":16,"cmb":28,"cmd":37,"cmd_special":"can't be tripped","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Run"},{"feat":"Skill Focus (Intimidate)"},{"feat":"Skill Focus (Perception)"},{"feat":"Step Up"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Appraise","value":16},{"skill":"Climb","value":31},{"skill":"Intimidate","value":25},{"skill":"Knowledge (planes)","value":19},{"skill":"Perception","value":25}],"languages":["Terran"],"special_abilities":[{"type":"Avalanche","kind":"Ex","details":"As a full-round action an avalanche legion can move up to twice its speed and overrun creatures in its path. This ability is identical to the trample universal monster rule, except the damage dealt is equal to the avalanche legion's troop attack (and creatures damaged by this ability are automatically affected by the avalanche legion's quake aura). Each creature occupying the avalanche legion's space or reach when it ends its movement takes an additional 2d6+6 points of damage."},{"type":"Earth Glide","kind":"Ex","details":"A burrowing avalanche legion can pass through stone, dirt, or almost any other sort of earth except metal as easily as a fish swims through water. If protected against fire damage, it can even glide through lava. This burrowing leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. A move earth spell cast on an area containing a burrowing avalanche legion flings the elemental back 30 feet, stunning the creature for 1 round unless it succeeds at a DC 15 Fortitude save."},{"type":"Quake Aura","kind":"Su","details":"An avalanche legion upturns and shatters natural earth or stone terrain within its space and in all adjacent spaces. This causes the space an avalanche legion occupies and all adjacent spaces to be treated as difficult terrain to creatures without the earth glide ability. A creature that ends its turn adjacent to an avalanche legion must succeed at a Reflex save (DC 23) or fall prone."},{"type":"Volley","kind":"Ex","details":"An avalanche legion troop can hurl a volley of rocks as a standard action. This attack takes the form of up to four lines with a range of 100 feet. These lines can start from the corner of any square in the troops space. All creatures in any of these lines take 4d8 points of bludgeoning damage (Reflex DC 19 half). The save DC is Dexterity-based and includes a +2 racial bonus."}],"before_combat":"An avalanche legion uses its earth glide ability  to travel below the ground and surprises enemies by erupting from below them.","during_combat":"An avalanche stays focused on a single opponent, moving only to keep the opponent within its space until that foe is dead.","morale":"An avalanche legion is absolutely loyal to Ayrzul and fights to the death.","source":"PFS 8-25"},{"name":"Pyroclasm Legion","cr":11,"xp":12800,"race":"Pyroclasm Legion","age_category":"Adult","alignment":"N","size":"Medium","type":"outsider","sub_types":["elemental","extraplanar","fire","troop"],"init":13,"senses":["darkvision 60 ft.","see invisibility"],"auras":["fire aura (DC 22)"],"ac":26,"ac_touch":20,"ac_flat_footed":16,"ac_mods":"+9 Dex, +1 dodge, +6 natural","hp":152,"hd":"16d10+64","hd_value":16,"fort":9,"ref":19,"will":12,"defensive_abilities":["troop traits"],"dr":"10/-","immunities":["elemental traits","fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":60}],"melee":"troop (4d6+8 plus burn)","ranged":"flame jet +25 touch (6d6 fire plus burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"4d6; DC 22"},{"type":"conflagration"},{"type":"flame jet","details":"6d6; 60 ft."},{"type":"hit and run"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]}],"strength":26,"dexterity":29,"constitution":18,"intelligence":10,"wisdom":11,"charisma":11,"baseatk":16,"cmb":24,"cmd":44,"cmd_special":"can't be tripped","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Stance"},{"feat":"Mobility"},{"feat":"Wind Stance"}],"skills":[{"skill":"Acrobatics","value":28,"special":"+12 to jump"},{"skill":"Climb","value":27},{"skill":"Fly","value":25},{"skill":"Intimidate","value":19},{"skill":"Knowledge (planes)","value":19},{"skill":"Perception","value":19}],"languages":["Ignan"],"special_abilities":[{"type":"Conflagration","kind":"Ex","details":"As a move action, a pyroclasm legion can join together to burn brighter and hotter, focusing their heat to create a powerful downdraft. This grants the troop a fly speed of 30 with average maneuverability for 1 round. The fire elemental troop can maintain this flight by expending a swift action at the start of its turn each round. While this ability is active, the troop's fire aura damage increases to 6d6."},{"type":"Fire Aura","kind":"Ex","details":"Creatures ending their turn within 10 ft. of a pyroclasm legion take 3d6 points of fire damage and must succeed at a Reflex save (DC 22) or catch fire as the troop's burn ability. This save DC is Constitution-based."},{"type":"Flame Jet","kind":"Su","details":"As a standard action, a pyroclasm legion can launch a jet of flame as a ranged touch attack at one creature within 60 feet. This attack deals 6d6 points of fire damage on a successful hit and creatures damaged by flame jet are affected by the pyroclasm legion's burn ability."},{"type":"Hit and Run","kind":"Ex","details":"A pyroclasm legion is trained to move and strike as a unit, allowing them to make a move or double move action and use their troop attack once against every creature in their space or in their reach at any point during their movement, rather than only at the end of movement."}],"during_combat":"A pyroclasm legion makes hit-and-run attacks.","source":"PFS 8-25"},{"name":"Ancient Magma Elemental","cr":15,"xp":51200,"race":"magma elemental","age_category":"elder","alignment":"N","size":"Huge","type":"outsider","sub_types":["earth","elemental","extraplanar","fire"],"templates_applied":"advanced","init":3,"senses":["darkvision 60 ft."],"ac":31,"ac_touch":7,"ac_flat_footed":31,"ac_mods":"-1 Dex, +24 natural, -2 size","hp":231,"hd":"22d10+110","hd_value":22,"fort":18,"ref":12,"will":10,"dr":"10/-","immunities":["bleed","critical hits","fire","flanking","paralysis","poison","precision damage","sleep","stunning"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"burrow","speed":20},{"type":"land","speed":20}],"speed_mod":"earth glide","melee":"2 slams +29 (3d8+9/19-20 plus burn)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon","details":"DC 26"},{"type":"burn","details":"3d8, DC 24"},{"type":"lava puddle"}],"strength":28,"dexterity":8,"constitution":21,"intelligence":12,"wisdom":13,"charisma":13,"baseatk":22,"cmb":33,"cmb_special":"+37 bull rush, overrun","cmd":42,"cmd_special":"44 vs. bull rush and overrun","feats":[{"feat":"Cleave"},{"feat":"Greater Bull Rush"},{"feat":"Greater Overrun"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (slam)"},{"feat":"Improved Initiative"},{"feat":"Improved Overrun"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":34},{"skill":"Intimidate","value":26},{"skill":"Knowledge (dungeoneering, planes)","value":26},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":26},{"skill":"Stealth","value":16}],"languages":["Ignan"],"special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"As a standard action, an ancient magma elemental can breathe a 60-foot cone of incandescent cinders. Every creature in the area takes 15d6 fire damage, and the cinders cling to and blind affected creatures as glitterdust for 2d6 rounds. With a successful DC 26 Reflex save, a target halves the damage, negates the blinding effect, and reduces the duration of the sparkling outline effect to 1 round. An ancient magma elemental can use this ability once every 1d6 rounds. The save DC is Constitution-based."},{"type":"Burn","kind":"Ex","details":"A magma elemental's burn DC includes a -2 racial penalty, as its fires don't burn quite as hot as true elemental flame."},{"type":"Earth Glide","kind":"Ex","details":"A burrowing magma elemental can pass through dirt, lava, stone, or almost any other sort of earth except metal as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple, though the area it passes through feels warm for 1 round afterward and often retains a strangely smooth texture, as if the stone had been polished. A move earth spell cast on an area containing a burrowing magma elemental flings the elemental back 30 feet, stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Lava Puddle","kind":"Su","details":"Once per day as a full-round action, a magma elemental can vomit forth a puddle of lava that fills its space to a depth of 2-3 inches and counts as difficult terrain. Any creature that moves through this puddle of lava takes 2d6 points of fire damage. This damage continues for 1d3 rounds after the creature leaves the lava pool, although then it only deals 1d6 points of fire damage per round. The lava puddle solidifies and is safe to touch after 22 rounds."}],"source":"PFS 8-25, Pathfinder RPG Bestiary 2 119"},{"name":"Vorvirex","cr":11,"xp":12800,"race":"young umbral dragon","age_category":"young","alignment":"CE","size":"Large","type":"dragon","sub_types":["extraplanar","fire"],"templates_applied":"fiery","init":5,"senses":["dragon senses"],"ac":26,"ac_touch":10,"ac_flat_footed":25,"ac_mods":"+4 armor, +1 Dex, +12 natural, -1 size","hp":104,"hd":"11d12+33","hd_value":11,"fort":10,"ref":8,"will":10,"defensive_abilities":["negative energy affinity"],"dr":"5/-","immunities":["cold","death effects","fire","negative energy","paralysis","sleep"],"speed":[{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"land","speed":40}],"melee":"bite +15 (2d6+7/19-20 plus 3d6 fire), 2 claws +15 (1d8+5 plus 3d6 fire), tail slap +13 (1d8+7 plus 3d6 fire), 2 wings +13 (1d6+2 plus 3d6 fire)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"40-ft. cone, 6d8 negative energy, Reflex DC 18 half"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":1,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"alarm"},{"spell":"mage armor"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"message"}]}],"strength":21,"dexterity":12,"constitution":17,"intelligence":16,"wisdom":17,"charisma":16,"baseatk":11,"cmb":17,"cmd":28,"cmd_special":"32 vs. trip","feats":[{"feat":"Hover"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":17},{"skill":"Fly","value":9},{"skill":"Knowledge (arcana, local, planes)","value":17},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":17},{"skill":"Stealth","value":11}],"languages":["Common","Abyssal","Draconic","Ignan"],"sq":["ghost bane","umbral scion"],"special_abilities":[{"type":"Ghost Bane","kind":"Su","details":"Vorvirex's physical attacks deal damage to incorporeal creatures normally."},{"type":"Umbral Scion","kind":"Ex","details":"Vorvirex has negative energy affinity and is immune to energy drain and death effects."}],"before_combat":"Vorvirex casts entropic shield and mage armor on himself.","during_combat":"Vorvirex engages the PCs from a distance using his breath weapon and sticking to the air. If facing opponents with superior ranged abilities, he instead lands and uses his natural attacks.","morale":"If Azhghazara is slain and Vorvirex is reduced to 15 or fewer hit points, he attempts to flee across the chasm and into the Plane of Fire.","source":"PFS 8-25, Pathfinder Player Companion: Monster Summoner's Handbook 19, Pathfinder RPG Bestiary 2 102"},{"name":"Nairoth","cr":17,"xp":102400,"race":"nightwalker","age_category":"Adult","alignment":"CE","size":"Huge","type":"undead","sub_types":["extraplanar","fire","nightshade"],"templates_applied":"fiery","init":2,"senses":["darksense","darkvision 60 ft.","low-light vision"],"auras":["desecrating aura (30 ft.)"],"ac":31,"ac_touch":10,"ac_flat_footed":29,"ac_mods":"+2 Dex, +21 natural, -2 size","hp":241,"hd":"21d8+105","hd_value":21,"fort":14,"ref":11,"will":19,"dr":"15/good and silver, 5/-","immunities":["cold","fire","undead traits"],"sr":27,"weaknesses":["light aversion"],"speed":[{"type":"land","speed":40}],"melee":"2 claws +27 (3d6+14/19-20 plus 3d6 fire and 4d6 cold)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"channel negative energy","details":"8/day, DC 29, 8d6"},{"type":"fear gaze"},{"type":"swift sundering"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"detect magic"},{"spell":"magic fang"}]},{"frequency":"at-will","spells":[{"spell":"contagion"},{"spell":"deeper darkness"},{"spell":"greater dispel magic"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"cone of cold"},{"spell":"finger of death"},{"spell":"plane shift"},{"spell":"summon","details":"4 greater shadows, level 7"}]},{"frequency":"3/day","spells":[{"spell":"confusion"},{"spell":"haste"},{"spell":"hold monster"},{"spell":"invisibility"},{"spell":"quickened unholy blight"}]}],"strength":35,"dexterity":14,"intelligence":20,"wisdom":21,"charisma":21,"baseatk":15,"cmb":31,"cmb_special":"+33 disarm, sunder","cmd":41,"cmd_special":"43 vs. disarm and sunder","feats":[{"feat":"Combat Expertise"},{"feat":"Command Undead"},{"feat":"Greater Sunder"},{"feat":"Greater Vital Strike"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Disarm"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (unholy blight)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana, religion)","value":29},{"skill":"Knowledge (planes)","value":26},{"skill":"Perception","value":29},{"skill":"Sense Motive","value":29},{"skill":"Spellcraft","value":29},{"skill":"Stealth","value":18,"special":"+8 in darkness"},{"skill":"Swim","value":33}],"languages":["Common","Abyssal","Draconic","Dwarven","Ignan","Infernal","telepathy 100 ft."],"special_abilities":[{"type":"Fear Gaze","kind":"Su","details":"Cower in fear for 1 round, 30 feet, Will DC 25 negates. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Swift Sundering","kind":"Su","details":"Nairoth can make a sunder attempt as a swift action with one of its claws."}],"during_combat":"Nairoth casts deeper darkness at the start of combat from within the cyclone of fire, followed by quickened unholy blight. It then casts haste and emerges from the cyclone, targets groups of enemies with cone of cold and individual spellcasters that prove to be able to penetrate its spell resistance with finger of death on subsequent rounds. If reduced to 120 of fewer hit points, Nairoth uses its summon ability to call 4 greater shadows.","source":"PFS 8-25, Pathfinder Player Companion: Monster Summoner's Handbook 19, Pathfinder RPG Bestiary 2 201"},{"name":"Vorvirex Subtier 14-15","cr":14,"xp":38400,"race":"young Adult umbral dragon","age_category":"young","alignment":"CE","size":"Huge","type":"dragon","sub_types":["extraplanar","fire"],"templates_applied":"fiery","init":4,"senses":["dragon senses"],"auras":["frightful presence (150 ft., DC 21)"],"ac":30,"ac_touch":8,"ac_flat_footed":30,"ac_mods":"+4 armor, +18 natural, -2 size","hp":157,"hd":"15d12+60","hd_value":15,"fort":13,"ref":9,"will":13,"defensive_abilities":["negative energy affinity"],"dr":"5/-","immunities":["cold","death effects","fire","negative energy","paralysis","sleep"],"sr":25,"speed":[{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"land","speed":40}],"melee":"bite +20 (2d8+10/19-20 plus 3d6 fire), 2 claws +20 (2d6+7 plus 3d6 fire), tail slap +18 (2d6+10 plus 3d6 fire), 2 wings +18 (1d8+3 plus 3d6 fire)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50-ft. cone, 10d8 negative energy, Reflex DC 21 half"},{"type":"crush","details":"Small creatures, DC 21, 2d8+10"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"vampiric touch"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":5,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"burning gaze"},{"spell":"command undead"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"mage armor"},{"spell":"protection from good"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"}]}],"strength":25,"dexterity":10,"constitution":19,"intelligence":18,"wisdom":19,"charisma":18,"baseatk":15,"cmb":24,"cmd":34,"cmd_special":"38 vs. trip","feats":[{"feat":"Hover"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":22},{"skill":"Diplomacy","value":22},{"skill":"Fly","value":10},{"skill":"Knowledge (arcana)","value":22},{"skill":"Knowledge (local)","value":22},{"skill":"Knowledge (planes)","value":22},{"skill":"Perception","value":22},{"skill":"Sense Motive","value":22},{"skill":"Spellcraft","value":22},{"skill":"Stealth","value":16}],"languages":["Common","Abyssal","Draconic","Ignan","Undercommon"],"sq":["ghost bane","umbral scion"],"special_abilities":[{"type":"Ghost Bane","kind":"Su","details":"Vorvirex's physical attacks deal damage to incorporeal creatures normally."},{"type":"Umbral Scion","kind":"Ex","details":"Vorvirex has negative energy affinity and is immune to energy drain and death effects."}],"before_combat":"Vorvirex casts entropic shield and mage armor on himself.","during_combat":"Vorvirex engages the PCs from a distance using his breath weapon and sticking to the air. If facing opponents with superior ranged abilities, he instead lands and uses his natural attacks.","morale":"If Azhghazara is slain and Vorvirex is reduced to 15 or fewer hit points, he attempts to flee across the chasm and into the Plane of Fire.","source":"PFS 8-25, Pathfinder Player Companion: Monster Summoner's Handbook 19, Pathfinder RPG Bestiary 2 102"},{"name":"Burning Stranger","cr":11,"xp":12800,"race":"pale stranger","age_category":"Adult","alignment":"NE","size":"Medium","type":"undead","sub_types":["fire"],"templates_applied":"fiery","init":9,"senses":["darkvision 60 ft."],"auras":["fear (10 ft., DC 21)"],"ac":23,"ac_touch":19,"ac_flat_footed":17,"ac_mods":"+5 Dex, +1 dodge, +3 luck, +4 natural","hp":127,"hd":"15d8+60","hd_value":15,"fort":9,"ref":12,"will":13,"defensive_abilities":["channel resistance +4"],"dr":"10/bludgeoning and magic, 5/-","immunities":["fire","undead traits"],"sr":21,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":30}],"ranged":"+1 pepperbox rifle +17 (1d10+1/x4 plus 3d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"stranger's shot"},{"type":"superheated weapons"}],"strength":17,"dexterity":21,"intelligence":11,"wisdom":18,"charisma":18,"baseatk":11,"cmb":14,"cmd":33,"feats":[{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Far Shot"},{"feat":"Improved Critical (pepperbox rifle)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Quick Draw"}],"skills":[{"skill":"Acrobatics","value":13},{"skill":"Climb","value":11},{"skill":"Intimidate","value":22},{"skill":"Perception","value":22},{"skill":"Ride","value":15},{"skill":"Stealth","value":13},{"skill":"Swim","value":8}],"languages":["Common"],"sq":["stranger's luck"],"special_abilities":[{"type":"Stranger's Luck","kind":"Su","details":"A burning stranger gains a +3 luck bonus to AC and has no chance of misfire when using firearms."},{"type":"Stranger's Shot","kind":"Ex","details":"As a full-round action, a burning stranger can take careful aim with its firearms and fire a single, ruinous shot. This single shot always resolves as a touch attack, regardless of the actual range. If the burning stranger threatens a critical hit with this sho t, it automatically confirms the critical hit . Regardless of whether the shot is a critical hit or no t, it deals 6d6 additional points of damage."},{"type":"Superheated Weapons","kind":"Su","details":"A burning stranger fights with a superheated pepperbox rifle fashioned from glowing-hot metal. This firearm has a range of 80 ft. and deals both bludgeoning and piercing damage. At a range of up to 80 feet, a burning stranger's firearm attacks resolve as touch attacks. While firearms normally consume bullets and black powder when fired, a burning stranger's pistols supernaturally reload the instant it fires them, allowing the undead to make multiple attacks in a round with the weapons. In addition, any pepperbox musket a burning stranger wields functions as a +1 pepperbox musket. A burning stranger doesn't provoke attacks of opportunity when it fires a superheated weapon in melee. When a burning stranger dies, its superheated weapon melts into a pile of slag."}],"gear":"pepperbox musket","during_combat":"A burning stranger stays within its first range increment and makes full attacks with a focus on heavily armored opponents.","source":"PFS 8-25, Pathfinder Player Companion: Monster Summoner's Handbook 19, Pathfinder RPG Bestiary 3 214"},{"name":"Aevarut","cr":17,"xp":102400,"race":"Aevarut","age_category":"Adult","alignment":"LN","size":"Large","type":"outsider","sub_types":["extraplanar","inevitable","lawful","mythic"],"init":15,"init_special":"M","senses":["darkvision 60 ft.","true seeing"],"auras":["ravages of time (30 ft., DC 26)"],"ac":33,"ac_touch":21,"ac_flat_footed":28,"ac_mods":"+7 deflection, +4 Dex, +1 dodge, +12 natural, -1 size","hp":278,"hd":"18d10+190","hd_value":18,"hp_mods":"regeneration (chaotic or horacalcum)","fort":16,"ref":12,"will":16,"defensive_abilities":["constructed","predictive defenses"],"dr":"10/ chaotic and epic","immunities":["aging"],"sr":31,"weaknesses":["horacalcum vulnerability"],"speed":[{"type":"climb","speed":40},{"type":"land","speed":40}],"melee":"2 slams +26 (2d6+9 plus erasure)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"correction","details":"DC 26"},{"type":"erasure","details":"DC 26"},{"type":"mythic power","details":"7/day, surge +1d10"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"blur"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"greater teleport"},{"spell":"locate creature"},{"spell":"locate object"},{"spell":"vision"}]},{"frequency":"3/day","spells":[{"spell":"freedom of movement"},{"spell":"haste"},{"spell":"plane shift"},{"spell":"quickened slow"}]},{"frequency":"1/week","spells":[{"spell":"discern location"},{"spell":"gate"},{"spell":"temporal stasis"}]}],"strength":28,"dexterity":19,"constitution":21,"intelligence":16,"wisdom":21,"charisma":24,"baseatk":18,"cmb":28,"cmd":50,"cmd_special":"54 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Power Attack","type":"mythic"},{"feat":"Quicken Spell-Like Ability (slow)"},{"feat":"Spring Attack"},{"feat":"Vital Strike","type":"mythic"}],"skills":[{"skill":"Climb","value":17},{"skill":"Diplomacy","value":28},{"skill":"Disable Device","value":22},{"skill":"Intimidate","value":28},{"skill":"Knowledge (arcana, history, planes)","value":24},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":26},{"skill":"Spellcraft","value":24}],"languages":["truespeech"],"sq":["erasure","out of town","slipstream","temporal anomaly"],"special_abilities":[{"type":"Correction","kind":"Su","details":"An aevarut can expend one use of mythic power as a move action to make amends to perceived \"errors\" in continuity by targeting a creature within 100 ft. and changing the course of future events, thereby absorbing the potential energy of actions that never happened. The target creature must succeed at a DC 26 Will save or become staggered until the end of its next turn. In return, the aevarut gains an additional standard or move action in the next round of combat. The save DC is Charisma-based."},{"type":"Erasure","kind":"Su","details":"When an aevarut successfully deals damage with a slam attack, its target must succeed at a DC 26 Will save or be temporarily erased from time for 1d4 rounds. A creature that fails this save ceases to exist, disappears instantly, and cannot be targeted by any spells or effects that attempt to reference the creature or interact with it. Such effects fail as if the target creature did not exist. After the duration of erasure expires, the target reappears exactly where it was as if no time had passed for it (and any remaining effects on the creature resume). If that space is occupied, it appears in the nearest unoccupied space. A creature that successfully saves against an aevarut's erasure ability cannot be affected by the same aevarut's erasure for 24 hours. Only a miracle or wish spell can prematurely end the effect of erasure. The save DC is Charisma-based."},{"type":"Horacalcum Vulnerability","kind":"Ex","details":"An aevarut's damage reduction and regeneration are bypassed by damage from horacalcum weapons. Critical threats made by a horacalcum weapon against an aevarut are automatically confirmed."},{"type":"Out of Time","kind":"Su","details":"An aevarut is a caretaker of time and can take actions when it would normally be affected by time stop. While in an area of a time stop spell, an aevarut is free to attack or otherwise interact with any other creatures that can act during the duration of the spell."},{"type":"Predictive Defense","kind":"Su","details":"An aevarut adds its Charisma modifier as a deflection bonus to its Armor Class."},{"type":"Ravages of Time","kind":"Su","details":"An aevarut's aura is disruptive to creatures that experience time in a linear direction. A living creature that begins its turn within 30 ft. of an aevarut must succeed at a DC 26 Fortitude save or become exhausted until it leaves the aevarut's aura. A creature that successfully saves against ravages of time is immune to the effects of this ability for 24 hours. The save DC is Charisma-based."},{"type":"Slipstream","kind":"Su","details":"An aevarut can spent one use of mythic power as a swift action to slip into the timestream and emerge anywhere within 50 feet. This ability overwhelms most teleportation countermeasures such as dimensional anchor. When an aevarut activates slipstream, it can attempt a caster level check (DC = 11 + the effect's caster level) against each such countermeasure; if successful, it ignores that countermeasure for the duration of the effect. The aevarut has a 75% chance to ignore any countermeasure that doesn't have a caster level."},{"type":"Temporal Anomaly","kind":"Su","details":"Once per day as a full-round action, an aevarut can expend one use of its mythic power to create a temporal anomaly that duplicates any creature it can see that whose total number of Hit Dice is no greater than half the aevarut's Hit Dice plus half its mythic tier. This is identical to the effect of a simulacrum spell, except the duplicate is made entirely of sand and shares a telepathic connection to the aevarut across any distance. A creature created by this ability lasts for 24 hours or until the inevitable dismisses it as a free action, and then collapses into a pile of glowing sand. An aevarut may not have more than one temporal anomaly active at a time."}],"before_combat":"Vector uses vision on each of the PCs to learn information about them. Then Vector spends 1 point of mythic power to use its temporal anomaly ability to create a simulacrum of Sorrina Westyr that contacts the PCs and attempts to dissuade them from their mission. Following that conversation, Vector casts freedom of movement on itself, haste on itself and its allies, and then gate to reach Kandirion's Forge.","during_combat":"Vector casts quickened slow on the first round of combat and then uses its correction ability on the most heavily armored opponent. It uses slipstream to close the distance with spellcasters, and pummels its greatest threats.","source":"PFS 8-25"},{"name":"Unwavering Path Acolyte","cr":11,"xp":12800,"race":"Axiomite","age_category":"Adult","classes":[{"class":"oracle","level":6}],"alignment":"LN","size":"Medium","type":"outsider","sub_types":["extraplanar","lawful"],"init":8,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":15,"ac_flat_footed":22,"ac_mods":"+6 armor, +4 Dex, +1 dodge, +6 natural","hp":152,"hd":"6d8+10d10+70","hd_value":16,"hp_mods":"regeneration 5 (chaotic or magic)","fort":11,"ref":15,"will":22,"dr":"10/chaotic","immunities":["disease","electricity","mind-affecting effects"],"resists":["cold 10","fire 10"],"sr":19,"speed":[{"type":"fly","speed":30,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"+1 axiomatic longspear +22 (1d8+11/x3 plus 2d6 vs. chaotic)","space":"5 ft.","reach":"5 ft. (10 ft. with longspear)","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon","details":"see text, 1 zelekhut, level 6"},{"spell":"true seeing"}]},{"frequency":"3/day","spells":[{"spell":"dispel chaos"},{"spell":"empowered order's wrath"},{"spell":"haste"},{"spell":"hold monster"},{"spell":"lightning bolt"},{"spell":"telekinesis"},{"spell":"true strike"}]}],"spellsknown_caster":"oracle","spellsknown_caster_level":6,"spellsknown_concentration":13,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"cure serious wounds"},{"spell":"protection from energy"},{"spell":"sands of time"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"cure moderate wounds"},{"spell":"gentle repose"},{"spell":"grace"},{"spell":"hold person"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"command"},{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"forbid action"},{"spell":"memory lapse"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"mending"},{"spell":"read magic"},{"spell":"stabilize"},{"spell":"virtue"}]}],"mystery":"time","strength":25,"dexterity":19,"constitution":18,"intelligence":19,"wisdom":22,"charisma":25,"baseatk":14,"cmb":21,"cmd":36,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Empower Spell-Like Ability (order's wrath)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Spring Attack"}],"skills":[{"skill":"Craft (weaving)","value":15},{"skill":"Diplomacy","value":26},{"skill":"Fly","value":7},{"skill":"Knowledge (arcana, history, nature)","value":14},{"skill":"Knowledge (planes)","value":23},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":23},{"skill":"Stealth","value":20},{"skill":"Survival","value":23}],"languages":["Common","Abyssal","Celestial","Draconic","Infernal"],"sq":["crystalline dust form","oracle's curse (clouded vision)","revelations (erase from time, time flicker)","unwavering blade"],"special_abilities":[{"type":"Crystalline Dust Form","kind":"Su","details":"An axiomite can shift between its solid body and one made of golden, crystalline dust as a free action once per round. In dust form, the axiomite looks like a shifting mass of glowing mathematical symbols and equations. In this form it can fly and gains the incorporeal quality; it can use spell-like abilities but cannot make physical attacks. In its solid form, an axiomite cannot fly. Both shapes are the axiomite's true form, and it doesn't revert to a different form if killed. A true seeing spell reveals both forms simultaneously."},{"type":"Summon Inevitable","kind":"Sp","details":"Once per day, four axiomites can join hands to summon a single zelekhut inevitable with 100% chance of success as a full-round action."},{"type":"Unwavering Blade","kind":"Su","details":"Any weapon an Unwavering Path acolyte wields (including its longspear) is treated as a +1 axiomatic weapon in addition to its other qualities. Weapons retain this quality for 1 round after the axiomite releases the weapon."}],"gear":"+2 chain shirt, mwk longspear, cloak of resistance +2","before_combat":"An Unwavering Path acolyte casts true seeing before combat begins.","during_combat":"The acolytes provide various forms of support to Vector, such as pinning down troublesome melee combatants, performing hit-and-run tactics, blasting enemies with empowered order's wrath, or even providing the inevitable healing. If harried by a vexing opponent, an acolyte attempts to erase the creature using its erase from time revelation.","source":"PFS 8-25, Pathfinder RPG Advanced Player's Guide 42, Pathfinder RPG Bestiary 2 36"},{"name":"Unwavering Path Acolyte Subtier 14-15","cr":15,"xp":51200,"race":"Axiomite","age_category":"Adult","classes":[{"class":"oracle","level":11}],"alignment":"LN","size":"Medium","type":"outsider","sub_types":["extraplanar","lawful"],"init":8,"senses":["blindsense 30 ft.","darkvision 60 ft."],"ac":30,"ac_touch":18,"ac_flat_footed":25,"ac_mods":"+6 armor, +3 deflection, +4 Dex, +1 dodge, +6 natural","hp":220,"hd":"11d8+10d10+116","hd_value":21,"hp_mods":"regeneration 5 (chaotic or magic)","fort":13,"ref":17,"will":25,"dr":"10/chaotic","immunities":["disease","electricity","mind-affecting effects"],"resists":["cold 10","fire 10"],"sr":19,"speed":[{"type":"fly","speed":30,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"+1 axiomatic longspear +26 (1d8+11/x3 plus 2d6 vs. chaotic)","space":"5 ft.","reach":"5 ft. (10 ft. with longspear)","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon","details":"see text, 1 zelekhut, level 6"},{"spell":"true seeing"}]},{"frequency":"3/day","spells":[{"spell":"dispel chaos"},{"spell":"empowered order's wrath"},{"spell":"haste"},{"spell":"hold monster"},{"spell":"lightning bolt"},{"spell":"telekinesis"},{"spell":"true strike"}]}],"spellsknown_caster":"oracle","spellsknown_caster_level":11,"spellsknown_concentration":19,"spellsknown":[{"spell_level":5,"spell_slots":5,"spells":[{"spell":"commune"},{"spell":"flame strike"},{"spell":"mass cure light wounds"},{"spell":"permanency"}]},{"spell_level":4,"spell_slots":8,"spells":[{"spell":"cure critical wounds"},{"spell":"death ward"},{"spell":"dismissal"},{"spell":"threefold aspect"},{"spell":"tongues"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"bestow curse"},{"spell":"cure serious wounds"},{"spell":"locate object"},{"spell":"protection from energy"},{"spell":"sands of time"},{"spell":"wind wall"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"calm emotions"},{"spell":"cure moderate wounds"},{"spell":"darkness"},{"spell":"gentle repose"},{"spell":"grace"},{"spell":"hold person"},{"spell":"zone of truth"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"command"},{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"forbid action"},{"spell":"memory lapse"},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"mending"},{"spell":"read magic"},{"spell":"spark"},{"spell":"stabilize"},{"spell":"virtue"}]}],"mystery":"Time","strength":25,"dexterity":19,"constitution":18,"intelligence":19,"wisdom":22,"charisma":26,"baseatk":18,"cmb":25,"cmd":40,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Empower Spell-Like Ability (order's wrath)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Spell Focus (evocation)"},{"feat":"Spring Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Craft (weaving)","value":15},{"skill":"Diplomacy","value":32},{"skill":"Fly","value":11},{"skill":"Knowledge (arcana, history, nature)","value":14},{"skill":"Knowledge (planes)","value":28},{"skill":"Perception","value":30},{"skill":"Sense Motive","value":30},{"skill":"Spellcraft","value":28},{"skill":"Stealth","value":27},{"skill":"Survival","value":30}],"languages":["Common","Abyssal","Celestial","Draconic","Infernal"],"sq":["crystalline dust form","oracle's curse (clouded vision)","revelations (aging touch, erase from time, time flicker, time hop)","unwavering blade"],"special_abilities":[{"type":"Crystalline Dust Form","kind":"Su","details":"An axiomite can shift between its solid body and one made of golden, crystalline dust as a free action once per round. In dust form, the axiomite looks like a shifting mass of glowing mathematical symbols and equations. In this form it can fly and gains the incorporeal quality; it can use spell-like abilities but cannot make physical attacks. In its solid form, an axiomite cannot fly. Both shapes are the axiomite's true form, and it doesn't revert to a different form if killed. A true seeing spell reveals both forms simultaneously."},{"type":"Summon Inevitable","kind":"Sp","details":"Once per day, four axiomites can join hands to summon a single zelekhut inevitable with 100% chance of success as a full-round action."},{"type":"Unwavering Blade","kind":"Su","details":"Any weapon an Unwavering Path acolyte wields (including its longspear) is treated as a +1 axiomatic weapon in addition to its other qualities. Weapons retain this quality for 1 round after the axiomite releases the weapon."}],"gear":"+2 chain shirt, mwk longspear, cloak of resistance +3","source":"PFS 8-25, Pathfinder RPG Advanced Player's Guide 42, Pathfinder RPG Bestiary 2 36"}];
